import { EventEmitter } from 'node:events';
async function main(): Promise<void> {
  const ee: any = new EventEmitter();
  const ctx: any = new EventEmitter();
  ctx.on('y', () => {});
  const done: Promise<void>[] = [];
  ee.on('x', (o: any, d: any): Promise<void> => {
    const p = (async (): Promise<void> => {
      const v: any = await d.later();
      console.log(o.listenerCount('y'), String(v));
      const w: any = await d.later();
      console.log(o.listenerCount('y'), String(w));
    })();
    done.push(p);
    return p;
  });
  ee.emit('x', ctx, { later() { return new Promise((r: any) => setTimeout(() => r(7), 5)); } });
  await Promise.all(done);
  console.log('done');
}
